  readFileSync(join(APP, "..", "lib", "i18n", "locales", "en.json"), "utf8"),
) as Record<string, string>;
const VI = JSON.parse(
  readFileSync(join(APP, "..", "lib", "i18n", "locales", "vi.json"), "utf8"),
) as Record<string, string>;

